static void skip_ws(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') ++(*p);
}

static int* parse_int_array(const char **p, int *size) {
    skip_ws(p);
    if (**p != '[') return NULL;
    ++(*p);

    int cap = 16;
    int n = 0;
    int *arr = (int*)malloc((size_t)cap * sizeof(int));
    if (!arr) return NULL;

    while (1) {
        skip_ws(p);
        if (**p == ']') {
            ++(*p);
            break;
        }

        char *end = NULL;
        long value = strtol(*p, &end, 10);
        if (end == *p) {
            free(arr);
            return NULL;
        }
        if (n == cap) {
            cap *= 2;
            int *tmp = (int*)realloc(arr, (size_t)cap * sizeof(int));
            if (!tmp) {
                free(arr);
                return NULL;
            }
            arr = tmp;
        }
        arr[n++] = (int)value;
        *p = end;

        skip_ws(p);
        if (**p == ',') ++(*p);
    }

    *size = n;
    return arr;
}

