    static int[] parseArray(String s) {
        s = s.trim();
        if (s.length() <= 2) return new int[0];
        String body = s.substring(1, s.length() - 1);
        String[] parts = body.split(",");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i].trim());
        }
        return arr;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();

        int open = line.indexOf('[', 1);
        int close = line.indexOf(']', open);
        int[] arr = parseArray(line.substring(open, close + 1));

        String rest = line.substring(close + 1, line.length() - 1).trim();
        if (rest.startsWith(",")) rest = rest.substring(1).trim();
        String[] tail = rest.split(",");
        int k = Integer.parseInt(tail[0].trim());
        int threshold = Integer.parseInt(tail[1].trim());

        int result = new Solution().numOfSubarrays(arr, k, threshold);
        System.out.println(result);
    }
}

